const MUTATE_Q = new Set(["bo’shliq", "chanoq", "chig’anoq", "chiziq", "do’mboq", "oraliq", "oyoq", "po’stloq", "qopqoq", "qo’ltiq", "quloq", "ravoq", "tarmoq", "tomoq", "to’piq", "to’siq", "uzunchoq", "yumaloq"]);
const MUTATE_K = new Set(["bo’lak", "burchak", "buyrak", "ichak", "kovak", "ko’krak", "ko’richak", "kurak", "kursak", "moyak", "mushak", "qovoq", "suyak", "taloq", "teshik", "tirsak", "yurak"]);
const POSTPOSITIVE = new Set(["breves", "brevis", "communis", "dorsalis", "externus", "internus", "lateralis", "longus", "magnus", "major", "maximus", "medialis", "medius", "minimus", "minor", "princeps", "profundus", "superficialis", "superioris", "tertius"]);
const SIDE_ROOTS = new Set(["chap", "lateral", "medial", "oldingi", "orqa", "o’ng", "o’rta", "pastki", "yuqori"]);
const GENERIC_SUPPRESS:Record<string,string> = {"bone": "suya", "muscle": "musha", "artery": "arteriya", "vein": "vena", "body": "tana", "gland": "bez", "nerve": "nerv", "ligament": "boylam", "joint": "bo’g’im", "vessel": "tomir", "valve": "qopqoq", "organ": "organ", "tendon": "pay", "tooth": "tish", "nucleus": "yadro", "finger": "barmoq", "thumb": "barmoq", "toe": "barmo", "vertebra": "umurtqa", "vertebral": "umurtqa", "mater": "parda", "process": "o’simta"};

const VOWELS = new Set(['a','e','i','o','u','A','E','I','O','U']);

function possessive(nounUz:string):string{
 if(!nounUz)return nounUz;
 if(nounUz.endsWith('q')&&MUTATE_Q.has(nounUz))return nounUz.slice(0,-1)+"g'i";
 if(nounUz.endsWith('k')&&MUTATE_K.has(nounUz))return nounUz.slice(0,-1)+'gi';
 if(VOWELS.has(nounUz[nounUz.length-1]))return nounUz+'si';
 return nounUz+'i';
}

function translateWord(w:string):string{
 if(w.includes('-'))return w.split('-').map(p=>p?translateWord(p):p).join('-');
 return GLOSSARY[w.toLowerCase()]??w;
}

function appendWord(out:string[],rawToken:string,translated:string){
 const lw=rawToken.toLowerCase();
 const suppress=GENERIC_SUPPRESS[lw];
 if(out.length&&suppress&&out[out.length-1].toLowerCase().includes(suppress))return;
 out.push(translated);
}

function translatePhrase(phrase:string):string{
 const tokens=phrase.split(' ').filter(Boolean);
 if(tokens.length>=2&&POSTPOSITIVE.has(tokens[tokens.length-1].toLowerCase())){
  const adjRaw=tokens.pop()!;
  const adjUz=translateWord(adjRaw);
  const rest:string[]=[];
  for(const t of tokens)appendWord(rest,t,translateWord(t));
  const insertAt=rest.length&&SIDE_ROOTS.has(rest[0].toLowerCase())?1:0;
  rest.splice(insertAt,0,adjUz);
  return rest.join(' ');
 }
 const out:string[]=[];
 for(const t of tokens)appendWord(out,t,translateWord(t));
 return out.join(' ');
}

/** Translate a single BodyParts3D structure/concept name into Uzbek. */
export function translateAnatomyName(name:string):string{
 const trimmed=name.trim();
 const ofIndex=trimmed.indexOf(' of ');
 if(ofIndex!==-1){
  const head=trimmed.slice(0,ofIndex);
  const tail=trimmed.slice(ofIndex+4);
  const headUz=translatePhrase(head);
  const tailUz=translateAnatomyName(tail);
  const parts=headUz.split(' ');
  parts[parts.length-1]=possessive(parts[parts.length-1]);
  return `${tailUz}ning ${parts.join(' ')}`;
 }
 return translatePhrase(trimmed);
}

/** Capitalize the first letter, for display as a title. */
export function capitalizeName(s:string):string{
 return s?s[0].toUpperCase()+s.slice(1):s;
}
